<template>
  <div class="page-container policy-page"><div class="panel filter-panel"><div class="panel-title"><span class="title-text">惠农政策查询</span><span class="title-extra">共 {{ filteredPolicies.length }} 条政策</span></div><el-form :inline="true"><el-form-item label="关键词"><el-input v-model="filters.keyword" clearable placeholder="标题、摘要、部门" style="width:250px" /></el-form-item><el-form-item label="类别"><el-select v-model="filters.category" clearable placeholder="全部" style="width:130px"><el-option v-for="item in categories" :key="item" :label="item" :value="item" /></el-select></el-form-item><el-form-item label="部门"><el-select v-model="filters.dept" clearable placeholder="全部" style="width:160px"><el-option v-for="item in depts" :key="item" :label="item" :value="item" /></el-select></el-form-item><el-form-item label="有效状态"><el-select v-model="filters.active" clearable placeholder="全部" style="width:120px"><el-option label="有效" :value="true" /><el-option label="已结束" :value="false" /></el-select></el-form-item><el-form-item><el-button @click="reset">重置</el-button></el-form-item></el-form></div>
    <div class="policy-content"><div class="panel list-panel"><div v-for="item in filteredPolicies" :key="item.id" class="policy-card" @click="showDetail(item)"><div class="policy-head"><el-tag size="small" :type="categoryType(item.category)">{{ item.category }}</el-tag><el-tag size="small" :type="item.active?'success':'info'" effect="plain">{{ item.active?'有效':'已结束' }}</el-tag><span>{{ item.publishDate }}</span></div><h3>{{ item.title }}</h3><p>{{ item.summary }}</p><div class="policy-meta"><span>{{ item.dept }}</span><span>{{ item.scope }}</span><el-button link type="primary">查看详情</el-button></div></div><el-empty v-if="!filteredPolicies.length" description="暂无符合条件的政策" /></div><div class="panel category-panel"><div class="panel-title"><span class="title-text">类别统计</span></div><div v-for="item in stats" :key="item.name" class="category-row"><span>{{ item.name }}</span><el-progress :percentage="item.percent" :show-text="false" /><b>{{ item.count }}</b></div><el-divider /><p>政策详情包含申报条件、办理流程和材料清单，便于基层和经营主体直接办理。</p></div></div>
    <el-drawer v-model="detailVisible" title="政策详情" size="560px"><template v-if="current"><h2 class="detail-title">{{ current.title }}</h2><el-descriptions :column="1" border><el-descriptions-item label="类别/状态">{{ current.category }} / {{ current.active?'有效':'已结束' }}</el-descriptions-item><el-descriptions-item label="发布部门">{{ current.dept }}</el-descriptions-item><el-descriptions-item label="有效期限">{{ current.effectiveDate }}</el-descriptions-item><el-descriptions-item label="适用范围">{{ current.scope }}</el-descriptions-item></el-descriptions><div class="detail-block"><h4>政策摘要</h4><p>{{ current.summary }}</p></div><div class="detail-block"><h4>申报条件</h4><p>{{ current.conditions }}</p></div><div class="detail-block"><h4>办理流程</h4><el-steps :active="current.process.length" direction="vertical"><el-step v-for="step in current.process" :key="step" :title="step" /></el-steps></div><div class="detail-block"><h4>所需材料</h4><p>{{ current.materials }}</p></div></template></el-drawer>
  </div>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'; import { fetchPolicies } from '@/api/gpm'; const policies=ref([]); const current=ref(null); const detailVisible=ref(false); const filters=reactive({keyword:'',category:'',dept:'',active:null}); const categories=computed(()=>[...new Set(policies.value.map(i=>i.category))]); const depts=computed(()=>[...new Set(policies.value.map(i=>i.dept))]); const filteredPolicies=computed(()=>policies.value.filter(i=>(!filters.keyword||`${i.title}${i.summary}${i.dept}`.includes(filters.keyword))&&(!filters.category||i.category===filters.category)&&(!filters.dept||i.dept===filters.dept)&&(filters.active===null||i.active===filters.active))); const stats=computed(()=>categories.value.map(name=>{const count=policies.value.filter(i=>i.category===name).length;return{name,count,percent:policies.value.length?Math.round(count/policies.value.length*100):0}})); const categoryType=c=>({补贴政策:'success',保险政策:'warning',管护制度:'primary',产业政策:'info'}[c]||'info'); const reset=()=>Object.assign(filters,{keyword:'',category:'',dept:'',active:null}); const showDetail=item=>{current.value=item;detailVisible.value=true}; onMounted(async()=>{policies.value=await fetchPolicies()})
</script>
<style lang="scss" scoped>.policy-page{gap:12px;overflow:auto}.filter-panel :deep(.el-form-item){margin-bottom:0}.policy-content{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:12px}.list-panel{padding:14px 16px}.policy-card{padding:15px 16px;border:1px solid var(--ah-border);border-radius:8px;margin-bottom:10px;cursor:pointer;transition:.2s}.policy-card:hover{border-color:var(--ah-primary);box-shadow:0 4px 12px rgba(15,94,181,.09)}.policy-head,.policy-meta{display:flex;align-items:center;gap:10px}.policy-head>span{margin-left:auto;color:var(--ah-text-secondary);font-size:12px}.policy-card h3{margin:10px 0 8px;font-size:16px}.policy-card p,.category-panel p{color:var(--ah-text-secondary);line-height:1.7;font-size:13px}.policy-meta{margin-top:10px;color:var(--ah-text-secondary);font-size:12px}.policy-meta .el-button{margin-left:auto}.category-row{display:grid;grid-template-columns:75px 1fr 20px;align-items:center;gap:8px;margin-bottom:16px;font-size:13px}.detail-title{font-size:19px;line-height:1.6}.detail-block{margin-top:18px;padding:14px;background:#f5f8fc;border-radius:8px}.detail-block h4{margin-bottom:8px}.detail-block p{color:var(--ah-text-secondary);line-height:1.8}@media(max-width:1000px){.policy-content{grid-template-columns:1fr}.category-panel{display:none}}</style>
